import numpy as np
xs = np.array([0.17, 0.4, 0.86])
def value(b, x):
    return float(sum(b[i] * x ** i for i in range(9)))
assert np.allclose(float(sum(value(sp8_family_coefficients(1), x) for x in xs)), target)

import numpy as np
def endpoints(b):
    return float(b[0]) + 10.0 * float(np.sum(b))
assert np.allclose(float(sum(endpoints(sp8_family_coefficients(L)) for L in range(8))), target)

